-- =====================================================================
-- Base de datos: MyAnimeList Top 10k (normalizada, 3NF)
-- Origen: archive.zip (8 CSV). Licencia del dataset: CC-BY-4.0
-- Generado: 2026-10-31
-- Motor: SQLite (compatible con Room). Esquema escrito tal y como lo
-- genera Room, para poder usarlo con createFromAsset().
-- =====================================================================
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

-- ---------------------------------------------------------------------
-- TABLAS PRINCIPALES
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `anime` (
  `anime_id` INTEGER NOT NULL,
  `title` TEXT NOT NULL,
  `score` REAL NOT NULL,
  `rank` INTEGER NOT NULL,
  `popularity` INTEGER NOT NULL,
  `members` INTEGER NOT NULL,
  `synopsis` TEXT,
  `start_date` TEXT,
  `end_date` TEXT,
  `type` TEXT NOT NULL,
  `episodes` INTEGER,
  `image_url` TEXT NOT NULL,
  PRIMARY KEY(`anime_id`)
);
CREATE INDEX IF NOT EXISTS `index_anime_rank` ON `anime` (`rank`);
CREATE INDEX IF NOT EXISTS `index_anime_type` ON `anime` (`type`);

CREATE TABLE IF NOT EXISTS `genre` (
  `genre_id` INTEGER NOT NULL,
  `name` TEXT NOT NULL,
  `category` TEXT NOT NULL,
  PRIMARY KEY(`genre_id`)
);

CREATE TABLE IF NOT EXISTS `company` (
  `company_id` INTEGER NOT NULL,
  `name` TEXT,
  `company_type` TEXT NOT NULL,
  `image_url` TEXT,
  PRIMARY KEY(`company_id`)
);

CREATE TABLE IF NOT EXISTS `character` (
  `character_id` INTEGER NOT NULL,
  `name` TEXT,
  `image_url` TEXT,
  PRIMARY KEY(`character_id`)
);

CREATE TABLE IF NOT EXISTS `person` (
  `person_id` INTEGER NOT NULL,
  `name` TEXT,
  `person_type` TEXT NOT NULL,
  `image_url` TEXT,
  PRIMARY KEY(`person_id`)
);
CREATE INDEX IF NOT EXISTS `index_person_person_type` ON `person` (`person_type`);

-- ---------------------------------------------------------------------
-- TABLAS DE RELACION (N:M)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `anime_genre` (
  `anime_id` INTEGER NOT NULL,
  `genre_id` INTEGER NOT NULL,
  PRIMARY KEY(`anime_id`, `genre_id`),
  FOREIGN KEY(`anime_id`) REFERENCES `anime`(`anime_id`) ON UPDATE NO ACTION ON DELETE CASCADE,
  FOREIGN KEY(`genre_id`) REFERENCES `genre`(`genre_id`) ON UPDATE NO ACTION ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS `index_anime_genre_genre_id` ON `anime_genre` (`genre_id`);

CREATE TABLE IF NOT EXISTS `anime_company` (
  `anime_id` INTEGER NOT NULL,
  `company_id` INTEGER NOT NULL,
  `role` TEXT NOT NULL,
  PRIMARY KEY(`anime_id`, `company_id`),
  FOREIGN KEY(`anime_id`) REFERENCES `anime`(`anime_id`) ON UPDATE NO ACTION ON DELETE CASCADE,
  FOREIGN KEY(`company_id`) REFERENCES `company`(`company_id`) ON UPDATE NO ACTION ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS `index_anime_company_company_id` ON `anime_company` (`company_id`);

CREATE TABLE IF NOT EXISTS `anime_character` (
  `anime_id` INTEGER NOT NULL,
  `character_id` INTEGER NOT NULL,
  `role` TEXT NOT NULL,
  PRIMARY KEY(`anime_id`, `character_id`),
  FOREIGN KEY(`anime_id`) REFERENCES `anime`(`anime_id`) ON UPDATE NO ACTION ON DELETE CASCADE,
  FOREIGN KEY(`character_id`) REFERENCES `character`(`character_id`) ON UPDATE NO ACTION ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS `index_anime_character_character_id` ON `anime_character` (`character_id`);

CREATE TABLE IF NOT EXISTS `anime_staff` (
  `anime_id` INTEGER NOT NULL,
  `person_id` INTEGER NOT NULL,
  `role` TEXT NOT NULL,
  PRIMARY KEY(`anime_id`, `person_id`),
  FOREIGN KEY(`anime_id`) REFERENCES `anime`(`anime_id`) ON UPDATE NO ACTION ON DELETE CASCADE,
  FOREIGN KEY(`person_id`) REFERENCES `person`(`person_id`) ON UPDATE NO ACTION ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS `index_anime_staff_person_id` ON `anime_staff` (`person_id`);

CREATE TABLE IF NOT EXISTS `character_voice_actor` (
  `character_id` INTEGER NOT NULL,
  `person_id` INTEGER NOT NULL,
  `language` TEXT NOT NULL,
  PRIMARY KEY(`character_id`, `person_id`, `language`),
  FOREIGN KEY(`character_id`) REFERENCES `character`(`character_id`) ON UPDATE NO ACTION ON DELETE CASCADE,
  FOREIGN KEY(`person_id`) REFERENCES `person`(`person_id`) ON UPDATE NO ACTION ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS `index_character_voice_actor_person_id` ON `character_voice_actor` (`person_id`);

-- ---------------------------------------------------------------------
-- DATOS
-- ---------------------------------------------------------------------

-- anime: 9999 filas

-- genre: 76 filas

-- company: 2074 filas

-- character: 39871 filas

-- person: 11405 filas

-- anime_genre: 31160 filas

-- anime_company: 56622 filas

-- anime_character: 87939 filas

-- anime_staff: 33827 filas

-- character_voice_actor: 41834 filas

COMMIT;
PRAGMA foreign_keys = ON;
PRAGMA user_version = 1;
